#include "mxh/server/plustime_manager.hpp"
#include <algorithm>
namespace mxh::server {namespace{bool before_end(const PlusTimeInfo&e,std::uint16_t d,std::uint16_t h,std::uint16_t m){if(e.end_day<d)return false;if(e.end_day==d&&(e.end_hour<h||(e.end_hour==h&&e.end_minute<=m)))return false;return true;}bool started(const PlusTimeInfo&e,std::uint16_t d,std::uint16_t h,std::uint16_t m){if(e.start_day!=d)return false;if(e.start_hour>h)return false;if(e.start_hour==h&&e.start_minute>m)return false;return true;}bool has(const PlusTimeState&s,std::uint16_t i){return std::find(s.applied.begin(),s.applied.end(),i)!=s.applied.end();}}
void plustime_reset(PlusTimeState&s){s.entries.clear();s.applied.clear();s.context.clear();}
std::vector<PlusTimeAction> plustime_process(PlusTimeState&s,std::uint16_t d,std::uint16_t h,std::uint16_t m){std::vector<PlusTimeAction>a;if(!s.toggle_on)return a;bool change=false;for(const auto&e:s.entries)if(!has(s,e.index)&&before_end(e,d,h,m)&&started(e,d,h,m)){s.context+=(s.context.empty()?"":", ")+e.context;a.push_back({PlusTimeActionKind::notify_on,e.event_index,0,e.title,s.context});a.push_back({PlusTimeActionKind::on,e.event_index,static_cast<std::uint16_t>(e.rate),{}, {}});s.applied.push_back(e.index);change=true;}for(auto it=s.applied.begin();it!=s.applied.end();){auto f=std::find_if(s.entries.begin(),s.entries.end(),[&](const auto&e){return e.index==*it;});if(f!=s.entries.end()&&f->end_day==d&&(f->end_hour<h||(f->end_hour==h&&f->end_minute<=m))){a.push_back({PlusTimeActionKind::off,f->event_index,0,{},{}});it=s.applied.erase(it);change=true;}else ++it;}if(!change)return a;s.context.clear();for(auto id:s.applied){auto f=std::find_if(s.entries.begin(),s.entries.end(),[&](const auto&e){return e.index==id;});if(f!=s.entries.end())s.context+=(s.context.empty()?"":", ")+f->context;}if(s.applied.empty()){a.push_back({PlusTimeActionKind::reset});a.push_back({PlusTimeActionKind::notify_off});}else a.push_back({PlusTimeActionKind::notify_on,0,0,{},s.context});return a;}
std::vector<PlusTimeAction> plustime_off(PlusTimeState&s){s.applied.clear();s.context.clear();s.toggle_on=false;return {{PlusTimeActionKind::notify_off},{PlusTimeActionKind::off}};}
std::vector<PlusTimeAction> plustime_connecting(const PlusTimeState&s){std::vector<PlusTimeAction>a;for(auto id:s.applied){auto f=std::find_if(s.entries.begin(),s.entries.end(),[&](const auto&e){return e.index==id;});if(f!=s.entries.end())a.push_back({PlusTimeActionKind::on,f->event_index,static_cast<std::uint16_t>(f->rate)});}return a;}
}
[[maybe_unused]] constexpr int plustime_manager_translation_unit_anchor=0;